<template><view class="page" :class="{on:isOn}"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">手电筒</text><text class="nav-icon" @click="isOn=!isOn">💡</text></view></view><view class="content"><view class="light-icon" :class="{on:isOn}">💡</view><view class="light-status">{{ isOn ? "已开启" : "已关闭" }}</view><view class="light-btn" @click="isOn=!isOn"><text>{{ isOn ? "关闭" : "开启" }}</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
